7	export const PLAN_PRICES: Record<string, number> = { free: 0, pro: 49, agency: 199 };
8	
9	export interface PlanDistribution { free: number; pro: number; agency: number; }
10	
11	export interface BillingStats {
12	  mrr: number;
13	  annualProjection: number;
14	  activeSubscriptions: number;
15	  freeUsers: number;
16	  planDistribution: PlanDistribution;
17	}
