24	async function fetchBillingStats(): Promise<BillingStats> {
25	  const supabase = createClient();
26	  const { data, error } = await supabase.from("profiles").select("plan");
27	  if (error) throw new Error(error.message);
28	
29	  const profiles = data ?? [];
30	  const planDistribution: PlanDistribution = { free: 0, pro: 0, agency: 0 };
31	
32	  for (const p of profiles) {
33	    const plan = p.plan as keyof PlanDistribution;
34	    if (plan in planDistribution) planDistribution[plan]++;
35	  }
36	
37	  const mrr = planDistribution.pro * PLAN_PRICES.pro + planDistribution.agency * PLAN_PRICES.agency;
38	
39	  return {
40	    mrr,
41	    annualProjection: mrr * 12,
42	    activeSubscriptions: planDistribution.pro + planDistribution.agency,
43	    freeUsers: planDistribution.free,
44	    planDistribution,
45	  };
46	}
