35	async function fetchAdminScans({ page, pageSize, filter, sortColumn, sortAsc }: FetchAdminScansParams): Promise<AdminScansResult> {
36	  const supabase = createClient();
37	  let query = supabase
38	    .from("scans")
39	    .select("*, profiles:user_id (email, full_name)", { count: "exact" })
40	    .order(sortColumn as string, { ascending: sortAsc });
41	
42	  if (filter.status) query = query.eq("status", filter.status);
43	  if (filter.scoreGte !== undefined && filter.scoreGte > 0) query = query.gte("overall_score", filter.scoreGte);
44	  if (filter.scoreLte !== undefined && filter.scoreLte < 100) query = query.lte("overall_score", filter.scoreLte);
45	  if (filter.dateFrom) query = query.gte("created_at", filter.dateFrom);
46	  if (filter.dateTo) query = query.lte("created_at", filter.dateTo);
47	
48	  const from = page * pageSize;
49	  const to = from + pageSize - 1;
50	  query = query.range(from, to);
51	
52	  const { data, count, error } = await query;
53	  if (error) throw new Error(error.message);
54	
55	  const scans: AdminScanRow[] = (data ?? []).map((row) => {
56	    const profileData = row.profiles as { email: string; full_name: string | null } | null;
57	    return {
58	      id: row.id, user_id: row.user_id, url: row.url, favicon_url: row.favicon_url,
59	      page_title: row.page_title, page_type: row.page_type, status: row.status,
60	      overall_score: row.overall_score, issues_found: row.issues_found, critical_issues: row.critical_issues,
61	      warnings: row.warnings, quick_wins: row.quick_wins, screenshot_url: row.screenshot_url,
62	      device: row.device, error_message: row.error_message, created_at: row.created_at,
63	      completed_at: row.completed_at, user_email: profileData?.email, user_name: profileData?.full_name ?? undefined,
64	    };
65	  });
66	
67	  const filtered = filter.search
68	    ? scans.filter((s) => s.url.toLowerCase().includes(filter.search!.toLowerCase()) || (s.user_email ?? "").toLowerCase().includes(filter.search!.toLowerCase()))
69	    : scans;
70	
71	  return { scans: filtered, total: filter.search ? filtered.length : (count ?? 0) };
72	}
