74	async function fetchAdminScanStats(): Promise<AdminScanStats> {
75	  const supabase = createClient();
76	  const todayStart = new Date();
77	  todayStart.setHours(0, 0, 0, 0);
78	
79	  const [
80	    { count: totalScans, error: totalError },
81	    { count: failedScans, error: failedError },
82	    { count: scansToday, error: todayError },
83	    { data: scoreData, error: scoreError },
84	  ] = await Promise.all([
85	    supabase.from("scans").select("*", { count: "exact", head: true }),
86	    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "failed"),
87	    supabase.from("scans").select("*", { count: "exact", head: true }).gte("created_at", todayStart.toISOString()),
88	    supabase.from("scans").select("overall_score").eq("status", "completed").not("overall_score", "is", null),
89	  ]);
90	
91	  if (totalError) throw new Error(totalError.message);
92	  if (failedError) throw new Error(failedError.message);
93	  if (todayError) throw new Error(todayError.message);
94	  if (scoreError) throw new Error(scoreError.message);
95	
96	  const scores = (scoreData ?? []).map((r) => r.overall_score as number).filter((s) => s !== null);
97	  const avgScore = scores.length > 0 ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
98	
99	  return { totalScans: totalScans ?? 0, avgScore, failedScans: failedScans ?? 0, scansToday: scansToday ?? 0 };
100	}
