102	export function useAdminScans(params: { page?: number; pageSize?: number; filter?: AdminScansFilter; sortColumn?: keyof ScanRow; sortAsc?: boolean; }) {
103	  const { page = 0, pageSize = 25, filter = {}, sortColumn = "created_at", sortAsc = false } = params;
104	  return useQuery({
105	    queryKey: ["admin", "scans", { page, pageSize, filter, sortColumn, sortAsc }],
106	    queryFn: () => fetchAdminScans({ page, pageSize, filter, sortColumn, sortAsc }),
