116	export function useDeleteScan() {
117	  const supabase = createClient();
118	  const queryClient = useQueryClient();
119	
120	  return useMutation({
121	    mutationFn: async (scanId: string) => {
122	      const { error: resultsError } = await supabase.from("scan_results").delete().eq("scan_id", scanId);
123	      if (resultsError) throw new Error(resultsError.message);
124	      const { error } = await supabase.from("scans").delete().eq("id", scanId);
