137	export function useAdminRetryScan() {
138	  const supabase = createClient();
139	  const queryClient = useQueryClient();
140	  const { user } = useAuth();
141	
142	  return useMutation({
143	    mutationFn: async (scanId: string) => {
144	      if (!user) throw new Error("Not authenticated");
145	      const { error: updateError } = await supabase.from("scans").update({ status: "pending", completed_at: null, error_message: null }).eq("id", scanId);
146	      if (updateError) throw new Error(updateError.message);
147	      const { error: fnError } = await supabase.functions.invoke("analyze-url", { body: { scanId } });
148	      if (fnError) console.warn("analyze-url function invocation warning:", fnError.message);
149	      await writeAuditLog(user.id, "retry_scan", "scan", scanId, {});
150	    },
151	    onSuccess: () => {
152	      toast.success("Scan queued for retry");
153	      queryClient.invalidateQueries({ queryKey: ["admin", "scans"] });
154	      queryClient.invalidateQueries({ queryKey: ["admin", "scan-stats"] });
155	    },
156	    onError: (error: Error) => { toast.error(`Failed to retry scan: ${error.message}`); },
157	  });
158	}
