21	async function fetchAdminStats(): Promise<AdminStats> {
22	  const supabase = createClient();
23	  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
24	  const todayMidnightUTC = new Date();
25	  todayMidnightUTC.setUTCHours(0, 0, 0, 0);
26	  const firstOfMonth = new Date();
27	  firstOfMonth.setDate(1);
28	  firstOfMonth.setHours(0, 0, 0, 0);
29	
30	  const [
31	    { count: totalUsers, error: usersError },
32	    { count: totalScans, error: scansError },
33	    { count: failedScans, error: failedError },
34	    { count: completedScans, error: completedError },
35	    { data: activeData, error: activeError },
36	    { count: newUsersToday, error: newUsersTodayError },
37	    { count: scansThisMonth, error: scansMonthError },
38	    { data: monthScores, error: monthScoresError },
39	  ] = await Promise.all([
40	    supabase.from("profiles").select("*", { count: "exact", head: true }),
41	    supabase.from("scans").select("*", { count: "exact", head: true }),
42	    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "failed"),
43	    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "completed"),
44	    supabase.from("scans").select("user_id").gte("created_at", sevenDaysAgo),
45	    supabase.from("profiles").select("*", { count: "exact", head: true }).gte("created_at", todayMidnightUTC.toISOString()),
46	    supabase.from("scans").select("*", { count: "exact", head: true }).gte("created_at", firstOfMonth.toISOString()),
47	    supabase.from("scans").select("overall_score").eq("status", "completed").gte("created_at", firstOfMonth.toISOString()).not("overall_score", "is", null),
48	  ]);
49	
50	  if (usersError) throw new Error(usersError.message);
51	  if (scansError) throw new Error(scansError.message);
52	  if (failedError) throw new Error(failedError.message);
53	  if (completedError) throw new Error(completedError.message);
54	  if (activeError) throw new Error(activeError.message);
55	  if (newUsersTodayError) throw new Error(newUsersTodayError.message);
56	  if (scansMonthError) throw new Error(scansMonthError.message);
57	  if (monthScoresError) throw new Error(monthScoresError.message);
58	
59	  const uniqueActiveUsers = new Set((activeData ?? []).map((r) => r.user_id)).size;
60	  const total = totalScans ?? 0;
61	  const completed = completedScans ?? 0;
62	  const scanSuccessRate = total > 0 ? Math.round((completed / total) * 1000) / 10 : 0;
63	  const scores = (monthScores ?? []).map((r) => r.overall_score as number).filter((s) => s !== null && s !== undefined);
64	  const avgScoreThisMonth = scores.length > 0 ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
65	
66	  return {
67	    totalUsers: totalUsers ?? 0, totalScans: total, activeUsers: uniqueActiveUsers,
68	    failedScans: failedScans ?? 0, scanSuccessRate, newUsersToday: newUsersToday ?? 0,
69	    avgScoreThisMonth, scansThisMonth: scansThisMonth ?? 0,
70	  };
71	}
