73	async function fetchUserGrowth(): Promise<UserGrowthDataPoint[]> {
74	  const supabase = createClient();
75	  const thirtyDaysAgo = subDays(new Date(), 30).toISOString();
76	
77	  const { data, error } = await supabase
78	    .from("profiles")
79	    .select("created_at")
80	    .gte("created_at", thirtyDaysAgo)
81	    .order("created_at", { ascending: true });
82	
83	  if (error) throw new Error(error.message);
84	
85	  const countsByDate: Record<string, number> = {};
86	  for (const row of data ?? []) {
87	    const day = format(new Date(row.created_at), "MMM d");
88	    countsByDate[day] = (countsByDate[day] ?? 0) + 1;
89	  }
90	
91	  const result: UserGrowthDataPoint[] = [];
92	  let cumulative = 0;
93	  for (let i = 29; i >= 0; i--) {
94	    const d = subDays(new Date(), i);
95	    const dateLabel = format(d, "MMM d");
96	    const count = countsByDate[dateLabel] ?? 0;
97	    cumulative += count;
98	    result.push({ date: dateLabel, count, cumulative });
99	  }
100	
101	  return result;
102	}
