104	async function fetchScanVolume(): Promise<ScanVolumeDataPoint[]> {
105	  const supabase = createClient();
106	  const sevenDaysAgo = subDays(startOfDay(new Date()), 6).toISOString();
107	
108	  const { data, error } = await supabase
109	    .from("scans")
110	    .select("created_at, status")
111	    .gte("created_at", sevenDaysAgo)
112	    .order("created_at", { ascending: true });
113	
114	  if (error) throw new Error(error.message);
115	
116	  const byDay: Record<string, { total: number; completed: number; failed: number }> = {};
117	
118	  for (const row of data ?? []) {
119	    const day = format(new Date(row.created_at), "EEE");
120	    if (!byDay[day]) byDay[day] = { total: 0, completed: 0, failed: 0 };
121	    byDay[day].total++;
122	    if (row.status === "completed") byDay[day].completed++;
123	    if (row.status === "failed") byDay[day].failed++;
124	  }
125	
126	  const result: ScanVolumeDataPoint[] = [];
127	  for (let i = 6; i >= 0; i--) {
128	    const day = format(subDays(new Date(), i), "EEE");
129	    const entry = byDay[day] ?? { total: 0, completed: 0, failed: 0 };
130	    result.push({ day, ...entry });
131	  }
132	
133	  return result;
134	}
