39	async function fetchAtRiskUsers(): Promise<AtRiskUser[]> {
40	  const supabase = createClient();
41	  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
42	
43	  const { data: profiles, error: profilesError } = await supabase.from("profiles").select("*").order("created_at", { ascending: false }).limit(200);
44	  if (profilesError) throw new Error(profilesError.message);
45	
46	  const { data: failedScansData, error: failedError } = await supabase.from("scans").select("user_id").eq("status", "failed").gte("created_at", sevenDaysAgo);
47	  if (failedError) throw new Error(failedError.message);
48	
49	  const { data: lastScans, error: lastScansError } = await supabase.from("scans").select("user_id, created_at").order("created_at", { ascending: false });
50	  if (lastScansError) throw new Error(lastScansError.message);
51	
52	  const failedUserIds = new Set((failedScansData ?? []).map((r) => r.user_id));
53	  const lastScanMap = new Map<string, string>();
54	  for (const scan of lastScans ?? []) {
55	    if (!lastScanMap.has(scan.user_id)) lastScanMap.set(scan.user_id, scan.created_at);
56	  }
57	
58	  const atRisk: AtRiskUser[] = [];
59	  for (const profile of profiles ?? []) {
60	    const p = profile as ProfileRow;
61	    const atLimit = p.scans_used >= p.scan_limit;
62	    const hasFailed = failedUserIds.has(p.id);
63	    const neverScanned = !lastScanMap.has(p.id);
64	    const lastScanDate = lastScanMap.get(p.id) ?? null;
65	
66	    if (atLimit || hasFailed || neverScanned) {
67	      atRisk.push({ ...p, has_failed_scans: hasFailed, never_scanned: neverScanned, at_scan_limit: atLimit, last_scan_date: lastScanDate });
68	    }
69	  }
70	
71	  return atRisk.sort((a, b) => {
72	    const scoreA = (a.at_scan_limit ? 3 : 0) + (a.has_failed_scans ? 2 : 0) + (a.never_scanned ? 1 : 0);
73	    const scoreB = (b.at_scan_limit ? 3 : 0) + (b.has_failed_scans ? 2 : 0) + (b.never_scanned ? 1 : 0);
74	    return scoreB - scoreA;
75	  });
76	}
