2	
3	/**
4	 * Feature Flags — stored in Supabase system_config table.
5	 *
6	 * Admin hook: read + write. For read-only use in app features, use hooks/use-feature-flag.ts.
7	 */
8	
9	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
10	import { createBrowserClient } from "@supabase/ssr";
11	import { toast } from "sonner";
12	
13	/**
14	 * Untyped client for system_config queries.
15	 * system_config is not in the Database generic — avoids `never` type inference.
16	 */
17	function createUntypedClient() {
18	  return createBrowserClient(
19	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
20	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
21	  );
22	}
23	
24	export interface FlagDefinition {
25	  key: string;
26	  label: string;
27	  description: string;
28	  defaultValue: boolean;
29	  category: "ui" | "feature" | "system";
30	  requiresSuperAdmin?: boolean;
31	}
32	
33	export const FLAG_DEFINITIONS: FlagDefinition[] = [
34	  {
35	    key: "agent_hub_enabled",
36	    label: "AI Agent Hub",
37	    description: "Show the AI Agent Hub section in the user sidebar navigation.",
38	    defaultValue: true,
39	    category: "ui",
40	  },
41	  {
42	    key: "integrations_enabled",
43	    label: "Integrations Page",
44	    description:
45	      "Show the Integrations page (Hotjar, GA4, Clarity, Search Console) in user navigation.",
46	    defaultValue: true,
47	    category: "ui",
48	  },
49	  {
50	    key: "pdf_export_enabled",
51	    label: "PDF Export",
52	    description:
53	      "Allow users to download audit reports as PDF. Requires a PDF generation service.",
54	    defaultValue: false,
55	    category: "feature",
56	  },
57	  {
58	    key: "email_notifications_enabled",
59	    label: "Email Notifications",
60	    description:
61	      "Send email alerts when scan completes, plan changes, or usage limit is reached.",
62	    defaultValue: false,
63	    category: "feature",
64	  },
65	  {
66	    key: "free_scan_enabled",
67	    label: "Public Scan (No Auth)",
68	    description:
69	      "Allow anonymous users to run a scan without signing in. Uses rate limiting.",
70	    defaultValue: true,
71	    category: "feature",
72	  },
73	  {
74	    key: "maintenance_mode",
75	    label: "Maintenance Mode",
76	    description:
77	      "Show a maintenance banner to all users. Does not block access — visual notice only.",
78	    defaultValue: false,
79	    category: "system",
80	    requiresSuperAdmin: true,
81	  },
82	];
83	
84	const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
85	  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
86	);
87	
88	export interface FeatureFlagsData {
89	  flags: Record<string, boolean>;
90	  updatedAt: string | null;
91	}
92	
93	async function fetchFeatureFlags(): Promise<FeatureFlagsData> {
94	  const supabase = createUntypedClient();
95	  const { data, error } = await supabase
96	    .from("system_config")
97	    .select("value, updated_at")
98	    .eq("key", "feature_flags")
99	    .single();
100	
101	  if (error && error.code !== "PGRST116") {
102	    // PGRST116 = row not found — that's fine, we use defaults
103	    throw new Error(error.message);
104	  }
105	
106	  const stored = (data?.value ?? {}) as Record<string, boolean>;
107	
108	  // Merge stored values with defaults (stored values take priority)
109	  const flags: Record<string, boolean> = { ...DEFAULT_FLAGS, ...stored };
110	
111	  return {
112	    flags,
113	    updatedAt: data?.updated_at ?? null,
114	  };
115	}
116	
117	// ── Admin hook: reads + writes ────────────────────────────────
118	
119	export function useFeatureFlags() {
120	  return useQuery({
121	    queryKey: ["admin", "feature-flags"],
122	    queryFn: fetchFeatureFlags,
123	    staleTime: 60_000,
124	  });
125	}
