133	      enabled,
134	      currentFlags,
135	    }: {
136	      key: string;
137	      enabled: boolean;
138	      currentFlags: Record<string, boolean>;
139	    }) => {
140	      const supabase = createUntypedClient();
141	      const mergedFlags = { ...currentFlags, [key]: enabled };
142	
143	      const { error } = await supabase.from("system_config").upsert(
144	        {
145	          key: "feature_flags",
146	          value: mergedFlags,
147	          updated_at: new Date().toISOString(),
148	        },
149	        { onConflict: "key" }
150	      );
151	
152	      if (error) throw new Error(error.message);
153	
154	      return { key, enabled, mergedFlags };
155	    },
156	    onSuccess: (result) => {
157	      const flagDef = FLAG_DEFINITIONS.find((f) => f.key === result.key);
158	      const label = flagDef?.label ?? result.key;
159	      toast.success(`${label} ${result.enabled ? "enabled" : "disabled"}`);
160	      // Invalidate both admin and app-level queries
161	      queryClient.invalidateQueries({ queryKey: ["admin", "feature-flags"] });
162	      queryClient.invalidateQueries({ queryKey: ["feature-flags"] });
163	    },
164	    onError: (error: Error) => {
165	      toast.error(`Failed to update flag: ${error.message}`);
166	    },
167	  });
168	}
